package com.example.facturaventa.config;
import javax.sql.DataSource;
import java.sql.*;
import org.springframework.context.annotation.*;
import org.springframework.boot.hibernate.autoconfigure.HibernatePropertiesCustomizer;
import org.springframework.jdbc.core.JdbcTemplate;
/** Completa la relación nueva antes del ddl-auto=update; conserva IDs e importes anteriores. */
@Configuration
public class MigracionListaPrecio {
 @Bean HibernatePropertiesCustomizer prepararModeloPrecios(DataSource source){return props->preparar(source);}
 public static void preparar(DataSource source) {
  try(Connection c=source.getConnection()) {
   if(!tabla(c,"lista_precio_articulo"))return;
   JdbcTemplate sql=new JdbcTemplate(source);
   if(tabla(c,"factura_venta_detalle")) {
    if(!columna(c,"factura_venta_detalle","porcentaje_bonificacion"))sql.execute("ALTER TABLE factura_venta_detalle ADD COLUMN porcentaje_bonificacion NUMERIC(5,2) DEFAULT 0 NOT NULL");
    if(!columna(c,"factura_venta_detalle","descripcion"))sql.execute("ALTER TABLE factura_venta_detalle ADD COLUMN descripcion VARCHAR(1200)");
    if(tabla(c,"articulo")&&columna(c,"lista_precio_articulo","articulo_id"))sql.execute("UPDATE factura_venta_detalle d SET descripcion=(SELECT a.descripcion FROM lista_precio_articulo p JOIN articulo a ON a.id=p.articulo_id WHERE p.id=d.lista_precio_articulo_id) WHERE d.descripcion IS NULL");
   }
   if(tabla(c,"cliente")&&!columna(c,"cliente","tipo_cliente"))sql.execute("ALTER TABLE cliente ADD COLUMN tipo_cliente VARCHAR(255) DEFAULT 'MINORISTA'");
   sql.execute("CREATE TABLE IF NOT EXISTS lista_precio (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, denominacion VARCHAR(255) NOT NULL UNIQUE, activo BOOLEAN DEFAULT TRUE NOT NULL, creado_en TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, modificado_en TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL)");
   if(!columna(c,"lista_precio_articulo","lista_precio_id"))sql.execute("ALTER TABLE lista_precio_articulo ADD COLUMN lista_precio_id BIGINT");
   var ids=sql.queryForList("SELECT id FROM lista_precio WHERE denominacion='General'",Long.class);
   if(ids.isEmpty()){sql.update("INSERT INTO lista_precio (denominacion,activo) VALUES ('General',TRUE)");ids=sql.queryForList("SELECT id FROM lista_precio WHERE denominacion='General'",Long.class);}
   sql.update("UPDATE lista_precio_articulo SET lista_precio_id=? WHERE lista_precio_id IS NULL",ids.get(0));
   sql.execute("ALTER TABLE lista_precio_articulo ALTER COLUMN lista_precio_id SET NOT NULL");
   // La columna antigua puede permanecer por compatibilidad, pero ya no forma parte de la entidad.
   if(columna(c,"factura_venta_detalle","articulo_id"))sql.execute("ALTER TABLE factura_venta_detalle ALTER COLUMN articulo_id DROP NOT NULL");
  }catch(SQLException e){throw new IllegalStateException("No se pudo actualizar el modelo de listas de precios",e);}
 }
 private static boolean tabla(Connection c,String name)throws SQLException{try(ResultSet r=c.getMetaData().getTables(null,c.getSchema(),"%",null)){while(r.next())if(name.equalsIgnoreCase(r.getString("TABLE_NAME")))return true;}return false;}
 private static boolean columna(Connection c,String table,String name)throws SQLException{try(ResultSet r=c.getMetaData().getColumns(null,c.getSchema(),"%","%")){while(r.next())if(table.equalsIgnoreCase(r.getString("TABLE_NAME"))&&name.equalsIgnoreCase(r.getString("COLUMN_NAME")))return true;}return false;}
}
